import os
import subprocess
import tempfile
import hashlib
import hmac
from flask import Flask, request, jsonify, send_file
from functools import wraps
import redis
import json

app = Flask(__name__)
app.config['UPLOAD_DIR'] = '/tmp/conversions'
app.config['MAX_CONTENT_LENGTH'] = 10 * 1024 * 1024

redis_client = redis.Redis(host=os.environ.get('REDIS_HOST', 'localhost'), port=6379, db=0)

def rate_limit(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        client_ip = request.headers.get('X-Forwarded-For', request.remote_addr)
        key = f'ratelimit:{client_ip}:{request.endpoint}'
        current = redis_client.incr(key)
        if current == 1:
            redis_client.expire(key, 60)
        if current > 30:
            return jsonify({'error': 'rate limited'}), 429
        return f(*args, **kwargs)
    return decorated

def verify_webhook_signature(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        signature = request.headers.get('X-Signature-256')
        if not signature:
            return jsonify({'error': 'missing signature'}), 401
        secret = os.environ.get('WEBHOOK_SECRET', '')
        expected = hmac.new(secret.encode(), request.data, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(f'sha256={expected}', signature):
            return jsonify({'error': 'invalid signature'}), 403
        return f(*args, **kwargs)
    return decorated

def sanitize_path(filename):
    """Prevent directory traversal in filenames"""
    basename = os.path.basename(filename)
    if not basename or basename.startswith('.'):
        return None
    return basename

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

@app.route('/api/v1/convert', methods=['POST'])
@rate_limit
def convert_document():
    """Convert documents between formats using LibreOffice headless mode"""
    if 'file' not in request.files:
        return jsonify({'error': 'no file provided'}), 400

    uploaded = request.files['file']
    output_format = request.form.get('format', 'pdf')

    # Validate output format
    allowed_formats = ['pdf', 'docx', 'odt', 'html', 'txt', 'rtf']
    if output_format not in allowed_formats:
        return jsonify({'error': f'unsupported format: {output_format}'}), 400

    safe_name = sanitize_path(uploaded.filename)
    if not safe_name:
        return jsonify({'error': 'invalid filename'}), 400

    # Check file extension
    allowed_extensions = ['.doc', '.docx', '.odt', '.rtf', '.html', '.txt', '.xlsx', '.pptx']
    ext = os.path.splitext(safe_name)[1].lower()
    if ext not in allowed_extensions:
        return jsonify({'error': f'unsupported input format: {ext}'}), 400

    work_dir = tempfile.mkdtemp(dir=app.config['UPLOAD_DIR'])
    input_path = os.path.join(work_dir, safe_name)
    uploaded.save(input_path)

    # Convert using LibreOffice
    cmd = f'libreoffice --headless --convert-to {output_format} --outdir {work_dir} {input_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            timeout=120,
            capture_output=True,
            cwd=work_dir
        )

        if result.returncode != 0:
            return jsonify({'error': 'conversion failed', 'detail': result.stderr.decode()[:200]}), 500

        # Find output file
        output_name = os.path.splitext(safe_name)[0] + '.' + output_format
        output_path = os.path.join(work_dir, output_name)

        if not os.path.exists(output_path):
            return jsonify({'error': 'output file not generated'}), 500

        return send_file(output_path, as_attachment=True, download_name=output_name)

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'conversion timed out'}), 504
    finally:
        # Cleanup handled by cron job on /tmp
        pass

@app.route('/api/v1/batch', methods=['POST'])
@rate_limit
def batch_convert():
    """Queue batch conversion job"""
    job_spec = request.get_json()
    if not job_spec or 'files' not in job_spec:
        return jsonify({'error': 'invalid job spec'}), 400

    job_id = hashlib.sha256(json.dumps(job_spec, sort_keys=True).encode()).hexdigest()[:16]
    redis_client.setex(f'job:{job_id}', 3600, json.dumps(job_spec))
    return jsonify({'job_id': job_id, 'status': 'queued'}), 202

if __name__ == '__main__':
    os.makedirs(app.config['UPLOAD_DIR'], exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
